    return myconv(next(), 1);
}

function next() {
    global $obj;
    return $obj->next();
}

function myconv($i, $no) {
    try {
        switch ($no) {
            case 1:
                return intval($i);
            case 2:
                return explode(' ', $i);
            case 4:
                return array_map('intval', explode(' ', $i));
            case 6:
                return str_split($i);
            case 7:
                return array_map('intval', str_split($i));
            case 8:
                return implode(' ', $i);
            case 9:
                return implode('\n', $i);
            case 0:
                return implode('', $i);
            default:
                return $i;
        }
    } catch (Exception $e) {
        return $i;
    }
}

class InputObject {
    public $list;
    public $index;
    public $max;

    function __construct($input) {
        $this->list = $input;
        $this->index = 0;
        $this->max = count($input);
    }

    function hasNext() {
        return ($this->index < $this->max);
    }

    function next() {
        if ($this->hasNext()) {
            return $this->list[$this->index++];
        } else {
            throw new Exception('ArrayIndexOutOfBoundsException');
        }
    }
}

$inLine = [];
while ($line = fgets(STDIN)) {
    $inLine[] = trim($line);
}
$obj = new InputObject($inLine);
Main();
?>
